/**
 * Real Harry Potter / Hogwarts Arc SVG Generators
 * Authentic Warner Bros movie aesthetic:
 * - Real live-action 35mm film stills (Harry Potter, Hermione Granger & Ron Weasley, Hogwarts Castle, Dumbledore)
 * - Gothic Hogwarts architecture, warm golden wand Lumos glow, and Marauder's Map parchment telemetry
 * - Dynamic profile bindings: name, handle, role, house points, grimoire repos, and live tech spells
 */

import { ReadmeProfileData, ReadmeConfig } from "../types/readme";

export const POTTER_HERO_HARRY_B64 = "";
export const POTTER_HERO_HERMIONE_B64 = "";
export const POTTER_HOGWARTS_CASTLE_B64 = "";
export const POTTER_DUMBLEDORE_CHIP_B64 = "";

function encodeSvgDataUri(svg: string): string {
  if (typeof window !== "undefined" && typeof window.btoa === "function") {
    return `data:image/svg+xml;base64,${window.btoa(unescape(encodeURIComponent(svg)))}`;
  }
  return `data:image/svg+xml;base64,${Buffer.from(svg).toString("base64")}`;
}

function escapeXml(unsafe: string): string {
  return unsafe
    .replace(/&/g, "&amp;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;")
    .replace(/"/g, "&quot;")
    .replace(/'/g, "&apos;");
}

export interface HouseTheme {
  name: string;
  colors: [string, string];
  crest: string;
  accent: string;
  motto: string;
}

export const HOGWARTS_HOUSES: Record<string, HouseTheme> = {
  gryffindor: {
    name: "Gryffindor",
    colors: ["#740001", "#D3A625"],
    crest: "🦁",
    accent: "#e7a93a",
    motto: "Where dwell the brave at heart",
  },
  slytherin: {
    name: "Slytherin",
    colors: ["#1A472A", "#AAAAAA"],
    crest: "🐍",
    accent: "#2ecc71",
    motto: "Greatness by any means",
  },
  ravenclaw: {
    name: "Ravenclaw",
    colors: ["#0E1A40", "#946B2D"],
    crest: "🦅",
    accent: "#3498db",
    motto: "Wit beyond measure is man's greatest treasure",
  },
  hufflepuff: {
    name: "Hufflepuff",
    colors: ["#ECB939", "#372E29"],
    crest: "🦡",
    accent: "#f39c12",
    motto: "Where they are just and loyal",
  },
};

/**
 * 1. HERO BANNER: Authentic live-action movie still of Harry Potter (or Hermione & Ron) casting Lumos on the Astronomy Tower
 */
export function createPotterHeroSvg(profile: ReadmeProfileData, config: ReadmeConfig): string {
  const name = escapeXml(profile.name || profile.username || "Harry Potter");
  const username = escapeXml(profile.username || "potter");
  const headline = escapeXml(
    config.header?.title || profile.bio?.split("\n")[0] || "Hogwarts Alumnus & Software Sorcerer"
  );
  const repos = String(profile.publicRepos ?? config.featuredRepos?.repos?.length ?? 42);
  const totalStars = config.featuredRepos?.repos?.reduce((acc, r) => acc + (r.stars || 0), 0) || 0;
  const stars = totalStars > 0 ? `${totalStars}+` : "25+";
  const followers = String(profile.followers ?? 108);

  const houseKey = config.potterHouse || "gryffindor";
  const house = HOGWARTS_HOUSES[houseKey] || HOGWARTS_HOUSES.gryffindor;

  const variant = config.animeVariant || "boy";
  const heroImageB64 = variant === "girl" ? POTTER_HERO_HERMIONE_B64 : POTTER_HERO_HARRY_B64;

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="0 0 1280 560" width="1280" height="560" role="img" aria-label="Hogwarts Lumos Hero — ${name}">
  <defs>
    <style>
      @keyframes shimmerBorder {
        0%, 100% { stroke-opacity: 0.4; }
        50% { stroke-opacity: 0.9; }
      }
      @keyframes floatCandle {
        0%, 100% { transform: translateY(0px); }
        50% { transform: translateY(-6px); }
      }
      .cinzel { font-family: 'Cinzel Decorative', 'Georgia', serif; }
      .sans { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; }
      .card-border { animation: shimmerBorder 5s ease-in-out infinite; }
      .floating { animation: floatCandle 4s ease-in-out infinite; }
    </style>

    <radialGradient id="bgDark" cx="30%" cy="50%" r="80%">
      <stop offset="0%" stop-color="#0e1424"/>
      <stop offset="60%" stop-color="#080b14"/>
      <stop offset="100%" stop-color="#04060a"/>
    </radialGradient>

    <linearGradient id="houseGrad" x1="0" y1="0" x2="1" y2="1">
      <stop offset="0%" stop-color="${house.colors[0]}"/>
      <stop offset="100%" stop-color="${house.colors[1]}"/>
    </linearGradient>

    <linearGradient id="goldNameGrad" x1="0" y1="0" x2="1" y2="0">
      <stop offset="0%" stop-color="#FFEAA7"/>
      <stop offset="35%" stop-color="#FDCB6E"/>
      <stop offset="75%" stop-color="#E17055"/>
      <stop offset="100%" stop-color="#D3A625"/>
    </linearGradient>

    <filter id="softGlow" x="-20%" y="-20%" width="140%" height="140%">
      <feGaussianBlur stdDeviation="5" result="blur"/>
      <feMerge>
        <feMergeNode in="blur"/>
        <feMergeNode in="SourceGraphic"/>
      </feMerge>
    </filter>
  </defs>

  <!-- Deep Moody Midnight Background -->
  <rect x="0" y="0" width="1280" height="560" rx="24" fill="url(#bgDark)"/>
  
  <!-- Outer Gold/House Shimmer Border -->
  <rect x="2" y="2" width="1276" height="556" rx="22" fill="none" stroke="url(#houseGrad)" stroke-width="1.8" class="card-border"/>

  <!-- Right Half: Authentic Movie Photography Still -->
  <g id="hero-film-still">
    <image x="420" y="14" width="846" height="532" preserveAspectRatio="xMidYMid slice" href="data:image/jpeg;base64,${heroImageB64}" clip-path="url(#artClip)"/>
    <clipPath id="artClip">
      <rect x="420" y="14" width="846" height="532" rx="18"/>
    </clipPath>
    <!-- Deep Vignette Gradient Blending Real Movie Scene into Dark Card UI -->
    <rect x="420" y="14" width="340" height="532" fill="url(#fadeLeft)"/>
    <linearGradient id="fadeLeft" x1="0" y1="0" x2="1" y2="0">
      <stop offset="0%" stop-color="#080b14" stop-opacity="1"/>
      <stop offset="45%" stop-color="#080b14" stop-opacity="0.8"/>
      <stop offset="80%" stop-color="#080b14" stop-opacity="0.25"/>
      <stop offset="100%" stop-color="#080b14" stop-opacity="0"/>
    </linearGradient>
  </g>

  <!-- Left Side: Hogwarts Dossier & Telemetry -->
  <!-- House Crest & Status Pill -->
  <g transform="translate(54, 48)">
    <rect x="0" y="0" width="280" height="36" rx="18" fill="#111625" stroke="${house.accent}" stroke-width="1" stroke-opacity="0.45"/>
    <text class="sans" x="14" y="23" font-size="14" fill="#ffd54f">${house.crest}</text>
    <text class="sans" x="38" y="23" font-size="12" font-weight="700" fill="${house.accent}" letter-spacing="0.8">${house.name.toUpperCase()} HOUSE</text>
    <circle cx="246" cy="18" r="4" fill="#2ecc71"/>
    <text class="sans" x="256" y="22" font-size="11" font-weight="600" fill="#2ecc71">ACTIVE</text>
  </g>

  <!-- Incantation / Terminal Summon Bar -->
  <g transform="translate(54, 114)">
    <text class="sans" font-family="monospace" font-size="13" fill="#f59e0b" opacity="0.95">⚡ ${username}@hogwarts:~$ accio --profile</text>
  </g>

  <!-- Greeting & Name -->
  <g transform="translate(54, 168)">
    <text class="sans" font-size="16" font-weight="600" fill="#94a3b8" letter-spacing="0.5">Mischief Managed, I'm</text>
    <text class="cinzel" y="58" font-size="52" font-weight="800" fill="url(#goldNameGrad)" filter="url(#softGlow)">${name}</text>
  </g>

  <!-- Wizard Headline / Role -->
  <g transform="translate(54, 268)">
    <text class="sans" font-size="15" font-weight="600" fill="#e2e8f0">🪄 ${headline}</text>
    <text class="sans" y="28" font-size="13" fill="#94a3b8" font-style="italic">"${house.motto}"</text>
  </g>

  <!-- Magical Telemetry Counters -->
  <g transform="translate(54, 348)">
    <!-- Stat 1: Spells & Repos -->
    <rect x="0" y="0" width="126" height="72" rx="14" fill="#111625" stroke="rgba(255,255,255,0.08)" stroke-width="1"/>
    <text class="sans" x="16" y="32" font-size="24" font-weight="800" fill="#f8fafc">${repos}</text>
    <text class="sans" x="16" y="54" font-size="11" font-weight="600" fill="#f59e0b" letter-spacing="0.5">GRIMOIRE REPOS</text>

    <!-- Stat 2: House Points / Stars -->
    <rect x="138" y="0" width="126" height="72" rx="14" fill="#111625" stroke="rgba(255,255,255,0.08)" stroke-width="1"/>
    <text class="sans" x="154" y="32" font-size="24" font-weight="800" fill="#f8fafc">${stars}</text>
    <text class="sans" x="154" y="54" font-size="11" font-weight="600" fill="#eab308" letter-spacing="0.5">HOUSE POINTS</text>

    <!-- Stat 3: Order Allies / Followers -->
    <rect x="276" y="0" width="126" height="72" rx="14" fill="#111625" stroke="rgba(255,255,255,0.08)" stroke-width="1"/>
    <text class="sans" x="292" y="32" font-size="24" font-weight="800" fill="#f8fafc">${followers}</text>
    <text class="sans" x="292" y="54" font-size="11" font-weight="600" fill="#38bdf8" letter-spacing="0.5">ORDER ALLIES</text>
  </g>

  <!-- Bottom Patronus Banner -->
  <g transform="translate(54, 464)">
    <rect x="0" y="0" width="402" height="44" rx="10" fill="#0d111c" stroke="rgba(211,166,37,0.3)" stroke-width="1"/>
    <text class="sans" x="16" y="27" font-size="12" fill="#cbd5e1">
      <tspan fill="#f59e0b" font-weight="700">PATRONUS:</tspan> Clean Architecture &amp; Zero Production Bugs
    </text>
  </g>
</svg>`;

  return encodeSvgDataUri(svg);
}

/**
 * 2. SPELLS ARSENAL: Dumbledore casting magical beam across the 15 dynamic tech spell chips
 */
export function createPotterSpellsStackSvg(profile: ReadmeProfileData, config: ReadmeConfig): string {
  const skillsList = config.skills?.selectedSkills || [];
  const topLangs = profile.topLanguages?.map((l) => l.name) || [];

  const combined = Array.from(new Set([...skillsList, ...topLangs]));
  const defaultStack = [
    "TypeScript", "React", "Python", "Node.js", "Next.js",
    "Rust", "Go", "SQL", "Docker", "GraphQL",
    "Git", "TailwindCSS", "AWS", "Linux", "C++"
  ];
  const finalStack = combined.length >= 5 ? combined.slice(0, 15) : defaultStack;
  while (finalStack.length < 15) {
    finalStack.push(defaultStack[finalStack.length]);
  }

  const houseKey = config.potterHouse || "gryffindor";
  const house = HOGWARTS_HOUSES[houseKey] || HOGWARTS_HOUSES.gryffindor;

  const cols = [462, 623, 784, 945, 1106];
  const rows = [136, 248, 360];
  const chips: string[] = [];

  const CHIP_PALETTE = [
    "#f59e0b", "#e11d48", "#3b82f6", "#10b981", "#8b5cf6",
    "#06b6d4", "#f97316", "#ec4899", "#14b8a6", "#6366f1"
  ];

  for (let i = 0; i < 15; i++) {
    const spell = escapeXml(finalStack[i]);
    const x = cols[i % 5];
    const y = rows[Math.floor(i / 5)];
    const color = CHIP_PALETTE[i % CHIP_PALETTE.length];
    const delay = (0.55 + i * 0.08).toFixed(2);
    const strokeDelay = (2.60 + i * 0.15).toFixed(2);

    chips.push(`
<g class="chip" style="animation-delay:${delay}s">
  <rect x="${x}" y="${y}" width="152" height="56" rx="14" fill="${color}" fill-opacity=".12"/>
  <rect x="${x + 0.6}" y="${y + 0.6}" width="150.8" height="54.8" rx="13.4" fill="none" stroke="${color}" stroke-opacity=".4">
    <animate attributeName="stroke-opacity" values=".4;.95;.4;.4" keyTimes="0;.05;.16;1" dur="6.30s" begin="${strokeDelay}s" repeatCount="indefinite"/>
  </rect>
  <text class="sans" x="${x + 76}" y="${y + 34}" font-size="14" font-weight="600" fill="#eef1f7" text-anchor="middle">${spell}</text>
</g>`);
  }

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="0 0 1280 500" width="1280" height="500" role="img" aria-label="Hogwarts Spells Arsenal — Tech Stack">
  <defs>
    <style>
      @keyframes flick { 0%,100%{opacity:.85} 50%{opacity:1} }
      @keyframes pop { 0%{opacity:0;transform:translateY(8px)} 100%{opacity:1;transform:translateY(0)} }
      .sans { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; }
      .cinzel { font-family: 'Cinzel Decorative', 'Georgia', serif; }
      .beam { animation: flick 4.5s ease-in-out infinite; }
      .chip { animation: pop .6s cubic-bezier(.2,.8,.2,1) both; }
    </style>

    <radialGradient id="bgDark" cx="50%" cy="50%" r="70%">
      <stop offset="0%" stop-color="#0e1424"/>
      <stop offset="100%" stop-color="#070913"/>
    </radialGradient>

    <linearGradient id="beamGold" x1="0" y1="0" x2="1" y2="0">
      <stop offset="0%" stop-color="#ffe082" stop-opacity=".95"/>
      <stop offset="20%" stop-color="#ffd54f" stop-opacity=".65"/>
      <stop offset="60%" stop-color="#ffb300" stop-opacity=".25"/>
      <stop offset="100%" stop-color="#ff8f00" stop-opacity=".02"/>
    </linearGradient>

    <radialGradient id="wandTip">
      <stop offset="0%" stop-color="#ffffff" stop-opacity="1"/>
      <stop offset="25%" stop-color="#fff8e1" stop-opacity=".9"/>
      <stop offset="60%" stop-color="#ffd54f" stop-opacity=".45"/>
      <stop offset="100%" stop-color="#ffca28" stop-opacity="0"/>
    </radialGradient>

    <filter id="softGlow" x="-30%" y="-30%" width="160%" height="160%">
      <feGaussianBlur stdDeviation="8"/>
    </filter>
  </defs>

  <rect width="1280" height="500" rx="24" fill="url(#bgDark)"/>
  <rect x="1" y="1" width="1278" height="498" rx="23" fill="none" stroke="${house.accent}" stroke-opacity=".35" stroke-width="1.4"/>

  <!-- Top Title -->
  <text class="sans" x="462" y="68" font-size="12" font-weight="700" fill="${house.accent}" letter-spacing="1.5">// THE ALCHEMIST'S SHELF &amp; CHARMS</text>
  <text class="cinzel" x="462" y="104" font-size="30" font-weight="800" fill="#f8fafc">Spells I cast daily</text>
  <text class="sans" x="1080" y="68" font-size="11" font-weight="700" fill="#94a3b8" letter-spacing="1">15 INCANTATIONS MASTERED</text>

  <!-- Left Wizard Caster Artwork (Real Dumbledore Film Still) -->
  <image x="28" y="42" width="380" height="417" preserveAspectRatio="xMidYMid slice" href="data:image/jpeg;base64,${POTTER_DUMBLEDORE_CHIP_B64}"/>

  <!-- Wand Lumos Beam Projecting to the Right (Origin at 398, 221) -->
  <g class="beam">
    <path d="M398 221 L1252 58 L1252 452 Z" fill="url(#beamGold)"/>
    <path d="M398 221 L1252 110 L1252 390 Z" fill="url(#beamGold)" opacity=".5" filter="url(#softGlow)"/>
    <circle cx="398" cy="221" r="52" fill="url(#wandTip)"/>
  </g>

  <!-- Dynamic Spells Grid -->
  ${chips.join("\n")}
</svg>`;

  return encodeSvgDataUri(svg);
}

/**
 * 3. HOGWARTS REGISTRY & MARAUDER'S MAP TELEMETRY: With real Hogwarts Castle cliffside backdrop
 */
export function createPotterMaraudersMapSvg(profile: ReadmeProfileData, config: ReadmeConfig): string {
  const name = escapeXml(profile.name || profile.username || "Wizard Scholar");
  const username = escapeXml(profile.username || "potter");
  const location = escapeXml(profile.location || "The Great Hall, Hogwarts");

  const houseKey = config.potterHouse || "gryffindor";
  const house = HOGWARTS_HOUSES[houseKey] || HOGWARTS_HOUSES.gryffindor;

  const topRepos = (config.featuredRepos?.repos?.filter(r => r.selected !== false) || []).slice(0, 5);

  const repoRows = topRepos.map((r, i) => {
    const y = 200 + i * 48;
    return `
    <g transform="translate(520, ${y})">
      <rect x="0" y="0" width="680" height="38" rx="8" fill="#111625" fill-opacity="0.88" stroke="rgba(255,255,255,0.08)"/>
      <text class="sans" x="16" y="24" font-size="14" fill="${house.accent}">📜</text>
      <text class="sans" x="42" y="24" font-size="13" font-weight="700" fill="#e2e8f0">${escapeXml(r.name.slice(0, 24))}</text>
      <text class="sans" x="580" y="24" font-size="12" fill="#f59e0b">⭐ ${r.stars || 0}</text>
      <text class="sans" x="630" y="24" font-size="12" fill="#94a3b8">🍴 ${r.forks || 0}</text>
    </g>`;
  }).join("\n");

  const svg = `<svg xmlns="http://www.w3.org/2000/svg" xmlns:xlink="http://www.w3.org/1999/xlink" viewBox="0 0 1280 520" width="1280" height="520" role="img" aria-label="Marauder's Map &amp; Hogwarts Dossier">
  <defs>
    <style>
      .sans { font-family: -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif; }
      .cinzel { font-family: 'Cinzel Decorative', 'Georgia', serif; }
    </style>
    <radialGradient id="bgDark" cx="50%" cy="50%" r="70%">
      <stop offset="0%" stop-color="#0e1424"/>
      <stop offset="100%" stop-color="#070913"/>
    </radialGradient>
  </defs>

  <rect width="1280" height="520" rx="24" fill="url(#bgDark)"/>
  
  <!-- Real Hogwarts Castle Backdrop overlayed on right with low opacity -->
  <g opacity="0.32">
    <image x="500" y="0" width="780" height="520" preserveAspectRatio="xMidYMid slice" href="data:image/jpeg;base64,${POTTER_HOGWARTS_CASTLE_B64}"/>
  </g>

  <rect x="1" y="1" width="1278" height="518" rx="23" fill="none" stroke="${house.accent}" stroke-opacity=".35" stroke-width="1.4"/>

  <!-- Header -->
  <text class="sans" x="60" y="60" font-size="12" font-weight="700" fill="${house.accent}" letter-spacing="1.5">// MARAUDER'S MAP TELEMETRY</text>
  <text class="cinzel" x="60" y="98" font-size="28" font-weight="800" fill="#f8fafc">Hogwarts Registry &amp; Quests</text>
  <text class="sans" x="60" y="126" font-size="13" fill="#94a3b8" font-style="italic">"I solemnly swear that I am up to no good."</text>

  <!-- Left: Student Dossier Badge -->
  <g transform="translate(60, 160)">
    <rect x="0" y="0" width="400" height="300" rx="16" fill="#111625" fill-opacity="0.95" stroke="rgba(211,166,37,0.3)" stroke-width="1.2"/>
    
    <!-- House Badge Header -->
    <rect x="16" y="16" width="368" height="44" rx="10" fill="${house.colors[0]}" fill-opacity="0.6"/>
    <text class="sans" x="32" y="43" font-size="20">${house.crest}</text>
    <text class="cinzel" x="64" y="43" font-size="16" font-weight="800" fill="#fff">${house.name.toUpperCase()} HOUSE</text>
    <text class="sans" x="310" y="43" font-size="11" font-weight="700" fill="#2ecc71">ENROLLED</text>

    <!-- Student Info -->
    <text class="sans" x="24" y="100" font-size="12" fill="#94a3b8">WIZARD / WITCH</text>
    <text class="cinzel" x="24" y="126" font-size="22" font-weight="800" fill="#f8fafc">${name}</text>
    
    <text class="sans" x="24" y="164" font-size="12" fill="#94a3b8">OWL ALIAS</text>
    <text class="sans" x="24" y="186" font-size="15" font-weight="700" fill="#38bdf8">@${username}</text>

    <text class="sans" x="24" y="224" font-size="12" fill="#94a3b8">COMMON ROOM</text>
    <text class="sans" x="24" y="246" font-size="14" font-weight="600" fill="#e2e8f0">${location.slice(0, 30)}</text>
  </g>

  <!-- Right: Top Spells / Repos Table -->
  <text class="sans" x="520" y="180" font-size="12" font-weight="700" fill="#cbd5e1" letter-spacing="1">ACTIVE MARAUDER DISPATCHES (TOP REPOSITORIES)</text>
  ${repoRows}
</svg>`;

  return encodeSvgDataUri(svg);
}
